import java.nio.file.*;import java.net.*;import java.util.*;import java.util.jar.*;import java.lang.reflect.*;import java.security.*;
public final class FinalProtocolRoundTrip {
 static List<String[]> catalog;
 static Class<?> type(ClassLoader l,String s)throws Exception{return Class.forName("school.magiccodex.protocol."+s,true,l);}
 static Object record(ClassLoader l,String s,Object...args)throws Exception{var c=type(l,s);var parts=c.getRecordComponents();return c.getDeclaredConstructor(Arrays.stream(parts).map(RecordComponent::getType).toArray(Class[]::new)).newInstance(args);}
 static byte[] encode(ClassLoader l,String protocol,Object obj)throws Exception{return (byte[])type(l,protocol).getMethod("encode",obj.getClass()).invoke(null,obj);}
 static Object decode(ClassLoader l,String protocol,String method,byte[] bytes)throws Exception{return type(l,protocol).getMethod(method,byte[].class).invoke(null,(Object)bytes);}
 static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 static void rejected(ClassLoader l,String protocol,String method,byte[] bytes)throws Exception{try{decode(l,protocol,method,bytes);throw new AssertionError("Legacy packet accepted "+protocol+"."+method);}catch(InvocationTargetException e){check(e.getCause() instanceof IllegalArgumentException,"Unexpected rejection "+e.getCause());}}
 static void equivalent(Object a,Object b){check(a.toString().equals(b.toString()),"Cross-loader record mismatch: "+a+" / "+b);}
 static void direction(ClassLoader sender,ClassLoader receiver,String label)throws Exception{
  var entries=new ArrayList<Object>();if(catalog!=null){for(var row:catalog)entries.add(record(sender,"TitleProtocol$Entry",row[0],Integer.parseInt(row[1]),new String(Base64.getDecoder().decode(row[2]),java.nio.charset.StandardCharsets.UTF_8),Integer.parseInt(row[3])));}else{for(int i=0;i<375;i++)entries.add(record(sender,"TitleProtocol$Entry","title_"+i,i%2,"title "+i,0xDEC58E));}String prefix=catalog==null?"title_0":catalog.stream().filter(x->x[1].equals("0")).map(x->x[0]).findFirst().orElse("");String suffix=catalog==null?"title_1":catalog.stream().filter(x->x[1].equals("1")).map(x->x[0]).findFirst().orElse("");String token="12345678-1234-1234-1234-123456789abc";
  Object titleResponse=record(sender,"TitleProtocol$Response",true,77L,token,9L,"verification",prefix,suffix,"",entries);byte[] responseBytes=encode(sender,"TitleProtocol",titleResponse);var decoded=decode(receiver,"TitleProtocol","response",responseBytes);equivalent(titleResponse,decoded);check(((List<?>)decoded.getClass().getMethod("entries").invoke(decoded)).size()==entries.size(),"Title catalog entries lost");byte[] v1=responseBytes.clone();v1[3]=1;rejected(receiver,"TitleProtocol","response",v1);
  Object titleRequest=record(sender,"TitleProtocol$Request",1,78L,token,9L,prefix,suffix);byte[] requestBytes=encode(sender,"TitleProtocol",titleRequest);equivalent(titleRequest,decode(receiver,"TitleProtocol","request",requestBytes));v1=requestBytes.clone();v1[3]=1;rejected(receiver,"TitleProtocol","request",v1);check(requestBytes.length<=1024,"Title request max");
  Object bagRequest=record(sender,"BagProtocol$Request",1,3);equivalent(bagRequest,decode(receiver,"BagProtocol","decodeRequest",encode(sender,"BagProtocol",bagRequest)));Object bagState=record(sender,"BagProtocol$State",3,3,true,"verified");equivalent(bagState,decode(receiver,"BagProtocol","decodeState",encode(sender,"BagProtocol",bagState)));
  Object offRequest=record(sender,"GeneralPresetModeProtocol$Request",79L,3);equivalent(offRequest,decode(receiver,"GeneralPresetModeProtocol","request",encode(sender,"GeneralPresetModeProtocol",offRequest)));Object offResponse=record(sender,"GeneralPresetModeProtocol$Response",79L,3,0);byte[] offBytes=encode(sender,"GeneralPresetModeProtocol",offResponse);equivalent(offResponse,decode(receiver,"GeneralPresetModeProtocol","response",offBytes));v1=offBytes.clone();v1[0]=1;rejected(receiver,"GeneralPresetModeProtocol","response",v1);
  System.out.println("PASS "+label+" Title"+entries.size()+"+v2request+v1rejection, Bag request/state, Preset OFF3+v1rejection; title response="+responseBytes.length+" bytes");
 }
 static Map<String,String> hashes(Path file,String prefix)throws Exception{var out=new TreeMap<String,String>();try(var jar=new JarFile(file.toFile())){for(var e:Collections.list(jar.entries()))if(e.getName().endsWith(".class")&&(e.getName().equals(prefix+".class")||e.getName().startsWith(prefix+"$"))){byte[] bytes=jar.getInputStream(e).readAllBytes();out.put(e.getName(),HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)));}}return out;}
 public static void main(String[] a)throws Exception{
  if(a.length>2)catalog=Files.readAllLines(Path.of(a[2])).stream().filter(x->!x.isBlank()).map(x->x.split("\t",-1)).toList();Path server=Path.of(a[0]),client=Path.of(a[1]);try(var sl=new URLClassLoader(new URL[]{server.toUri().toURL()},ClassLoader.getPlatformClassLoader());var cl=new URLClassLoader(new URL[]{client.toUri().toURL()},ClassLoader.getPlatformClassLoader())){
   for(var loader:List.of(sl,cl)){var custom=Class.forName("school.magiccodex.protocol.KyudichiQueueProtocol$Custom",false,loader);custom.getDeclaredMethods();custom.getDeclaredConstructors();custom.getDeclaredFields();check(type(loader,"KyudichiQueueProtocol$ToProxy").isAssignableFrom(custom),"Custom must implement permitted ToProxy");System.out.println("PASS Custom record JVM sealed metadata");check(type(loader,"TitleProtocol").getField("MAX_TITLES").getInt(null)==65535,"Title count bound not v2");check(type(loader,"TitleProtocol").getField("MAX_BYTES").getInt(null)==1_000_000,"Title response byte bound not v2");check(type(loader,"GeneralPresetModeProtocol").getField("OFF").getInt(null)==3,"Preset OFF missing");}
   direction(sl,cl,"server->client");direction(cl,sl,"client->server");
   for(String protocol:List.of("TitleProtocol","BagProtocol","GeneralPresetModeProtocol")){String prefix="school/magiccodex/protocol/"+protocol;var sh=hashes(server,prefix);var ch=hashes(client,prefix);check(!sh.isEmpty()&&sh.equals(ch),"Protocol class SHA mismatch "+protocol+" server="+sh+" client="+ch);System.out.println("PASS identical protocol class SHA256 "+protocol+" "+sh);}
  }
  System.out.println("PASS FINAL_ARTIFACT_PROTOCOL_INTEROP server="+server+" client="+client);
 }
}
